#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=6
REPO="applied-chaos/elgato-hd60s-mac"
TEAM="46A7P6HL4Z"
cd "$(dirname "$0")/.."

expand() { local p="$1"; p="${p/#\~/$HOME}"; printf '%s' "$p"; }

# ask_file KEY "Prompt" DEFAULT: keeps asking until the path exists.
ask_file() {
  local key="$1" prompt="$2" def="${3:-}" path
  while true; do
    [[ -n "$def" ]] && note "default: $def (press Enter)"
    ask _path "$prompt"
    path=$(expand "${_path:-$def}")
    [[ -f "$path" ]] && break
    warn "no file at $path"
  done
  printf -v "$key" '%s' "$path"
}

# check_profile FILE BUNDLE_ID: sanity-checks a downloaded provisioning profile.
check_profile() {
  local file="$1" bundle="$2" plist appid
  plist=$(security cms -D -i "$file" 2>/dev/null) || { warn "not a provisioning profile"; return 1; }
  appid=$(plutil -extract Entitlements.com\\.apple\\.application-identifier raw - <<<"$plist" 2>/dev/null || true)
  if [[ "$appid" != "$TEAM.$bundle" ]]; then
    warn "profile is for '$appid', expected $TEAM.$bundle"; return 1
  fi
  if plutil -extract ProvisionsAllDevices raw - <<<"$plist" >/dev/null 2>&1; then
    note "Developer ID profile: $(plutil -extract Name raw - <<<"$plist"), expires $(plutil -extract ExpirationDate raw - <<<"$plist")"
  else
    warn "this isn't a Developer ID profile (pick Distribution → Developer ID)"; return 1
  fi
}

GROUP="$TEAM.net.mintopia.hd60s"

# check_group FILE: the app and camera both read settings.json from this App Group, so each profile must carry it.
check_group() {
  if security cms -D -i "$1" | plutil -extract Entitlements.com\\.apple\\.security\\.application-groups json -o - - 2>/dev/null | grep -q "\"$GROUP\""; then
    return 0
  fi
  warn "profile lacks the App Group $GROUP: add App Groups to the App ID with that group, then regenerate the profile"
  return 1
}

banner "HD60S release signing secrets"

stage "Preflight"
say "Checks the tools this wizard needs, then sets secrets on $REPO."
if ! command -v gh >/dev/null || ! gh auth status >/dev/null 2>&1; then warn "run 'gh auth login' first"; exit 1; fi
[[ "$(gh repo view --json nameWithOwner --jq .nameWithOwner 2>/dev/null)" == "$REPO" ]] \
  || { warn "gh isn't pointing at $REPO from $(pwd)"; exit 1; }
xcrun --find notarytool >/dev/null 2>&1 || { warn "install Xcode first"; exit 1; }
say "You need to be the Account Holder of team $TEAM to create a Developer ID certificate,"
say "and Admin or Account Holder in App Store Connect to create an API key."
note "gh, Xcode and repo all look good."
pause

stage "Developer ID Application certificate"
if security find-identity -v -p codesigning | grep -q "Developer ID Application:.*($TEAM)"; then
  say "Found a Developer ID Application certificate for $TEAM in your keychain."
else
  say "No Developer ID Application certificate in your keychain. Create one in Xcode:"
  step "Xcode → Settings → Accounts → select your Apple ID → team $TEAM → Manage Certificates…"
  step "Click + (bottom left) → Developer ID Application. Close the sheet."
  open -a Xcode >/dev/null 2>&1 || true
  pause "Press Enter once it's created"
  security find-identity -v -p codesigning | grep -q "Developer ID Application:.*($TEAM)" \
    || warn "still can't see it; carry on if Keychain Access shows it"
fi
P12_PASSWORD=$(openssl rand -base64 18)
say "Now export it with its private key:"
step "Keychain Access → login keychain → My Certificates."
step "Right-click 'Developer ID Application: … ($TEAM)' → Export… → save as ~/Desktop/developer-id.p12"
step "When asked for a password, use this one (copy it now):"
printf '\n      %s%s%s\n\n' "$BOLD" "$P12_PASSWORD" "$RESET"
open -a "Keychain Access" >/dev/null 2>&1 || true
p12_opens() {
  openssl pkcs12 -in "$P12_FILE" -passin "pass:$P12_PASSWORD" -nokeys -legacy 2>/dev/null | grep -q "Developer ID Application" \
    || openssl pkcs12 -in "$P12_FILE" -passin "pass:$P12_PASSWORD" -nokeys 2>/dev/null | grep -q "Developer ID Application"
}
ask_file P12_FILE "Path to the exported .p12:" "$HOME/Desktop/developer-id.p12"
until p12_opens; do
  warn "that .p12 doesn't open with the password or has no Developer ID Application certificate."
  ask_secret P12_PASSWORD "Type the password you used (or Ctrl-C and export again):"
done
set_secret MACOS_CERTIFICATE_P12 "$(base64 -i "$P12_FILE")"
set_secret MACOS_CERTIFICATE_PASSWORD "$P12_PASSWORD"
if confirm "Delete $P12_FILE now it's uploaded? (it holds your signing key)"; then
  rm -P "$P12_FILE" 2>/dev/null || rm -f "$P12_FILE"; note "deleted"
fi
pause

stage "App IDs"
say "Local Xcode builds usually registered both App IDs already. Check them:"
open_url "https://developer.apple.com/account/resources/identifiers/list"
step "net.mintopia.hd60s must exist, with System Extension and App Groups ticked under Capabilities."
step "net.mintopia.hd60s.camera must exist, with App Groups ticked."
step "Both App IDs need the App Group $GROUP (Configure next to App Groups; add the group first under Identifiers → App Groups if it isn't listed)."
step "The app and camera Developer ID profiles must include that group, so regenerate any profile made before you added it."
step "If an App ID is missing: + → App IDs → App → Explicit Bundle ID, tick the capabilities, Register."
pause "Press Enter once both are there"

stage "Provisioning profile: app"
open_url "https://developer.apple.com/account/resources/profiles/add"
step "Distribution → Developer ID → Continue."
step "App ID: net.mintopia.hd60s → Continue."
step "Select the Developer ID Application certificate you just exported → Continue."
step "Name it 'HD60S App Developer ID' → Generate → Download."
until ask_file APP_PROFILE_FILE "Path to the downloaded profile:" "$HOME/Downloads/HD60S_App_Developer_ID.provisionprofile" \
      && check_profile "$APP_PROFILE_FILE" net.mintopia.hd60s && check_group "$APP_PROFILE_FILE"; do :; done
security cms -D -i "$APP_PROFILE_FILE" | grep -q "com.apple.developer.system-extension.install" \
  || warn "profile lacks the System Extension entitlement: tick it on the App ID and regenerate"
set_secret MACOS_APP_PROFILE "$(base64 -i "$APP_PROFILE_FILE")"
pause

stage "Provisioning profile: camera extension"
open_url "https://developer.apple.com/account/resources/profiles/add"
step "Distribution → Developer ID → Continue."
step "App ID: net.mintopia.hd60s.camera → Continue."
step "Select the same Developer ID Application certificate → Continue."
step "Name it 'HD60S Camera Developer ID' → Generate → Download."
until ask_file CAMERA_PROFILE_FILE "Path to the downloaded profile:" "$HOME/Downloads/HD60S_Camera_Developer_ID.provisionprofile" \
      && check_profile "$CAMERA_PROFILE_FILE" net.mintopia.hd60s.camera && check_group "$CAMERA_PROFILE_FILE"; do :; done
set_secret MACOS_CAMERA_PROFILE "$(base64 -i "$CAMERA_PROFILE_FILE")"
pause

stage "App Store Connect API key (notarisation)"
open_url "https://appstoreconnect.apple.com/access/integrations/api"
step "Team Keys tab → + (Generate API Key). Name: 'elgato-hd60s-mac notarisation', Access: Developer."
step "Copy the Issuer ID shown above the table."
ask ASC_ISSUER_ID "Issuer ID:"
step "Copy the new key's Key ID."
ask ASC_KEY_ID "Key ID:"
step "Click Download for that key (Apple only lets you download it once)."
until ask_file ASC_KEY_FILE "Path to the .p8:" "$HOME/Downloads/AuthKey_${ASC_KEY_ID}.p8"; do :; done
say "Checking the key with notarytool…"
if xcrun notarytool history --key "$ASC_KEY_FILE" --key-id "$ASC_KEY_ID" --issuer "$ASC_ISSUER_ID" >/dev/null 2>&1; then
  note "key works"
else
  warn "notarytool rejected the key; check the IDs (the secrets are set anyway so you can re-run)"
fi
set_secret ASC_KEY_P8 "$(base64 -i "$ASC_KEY_FILE")"
set_secret ASC_KEY_ID "$ASC_KEY_ID"
set_secret ASC_ISSUER_ID "$ASC_ISSUER_ID"
say "Keep the .p8 somewhere safe (a password manager); Apple won't let you download it again."
pause

finish
say "Next: merge develop into main, then push a tag, e.g. git tag v0.1.0 && git push origin v0.1.0"
}

run_wizard "$@"; exit
